231	
232	.btn-destructive:hover:not(:disabled) {
233	  background: var(--danger-hover);
234	}
235	
236	.btn-destructive:active:not(:disabled) {
237	  background: var(--danger-active);
238	}
239	
240	.btn-destructive:disabled {
241	  background: var(--danger-dis-bg);
242	  color: var(--danger-dis-text);
243	  cursor: not-allowed;
244	}
245	
246	/* Simulated states */
247	.btn-destructive.sim-hover  { background: var(--danger-hover); }
248	.btn-destructive.sim-active { background: var(--danger-active); transform: translateY(1px); box-shadow: none; }
249	.btn-destructive.sim-focus  { box-shadow: 0 0 0 3px var(--focus-ring); outline: none; }
