383	/* ─── Link-style Button ─────────────────────────────────────── */
384	/*
385	 * A <button> styled as an inline text link. Use for low-emphasis inline
386	 * actions: "Reset to default", "Clear all", "Show more", "Add another".
387	 */
388	
389	.btn-link {
390	  display: inline;
391	  background: transparent;
392	  border: none;
393	  padding: 0;
394	  color: var(--grey);
395	  text-decoration: underline;
396	  text-underline-offset: 2px;
397	  cursor: pointer;
398	  font-family: inherit;
399	  font-size: inherit;
400	  font-weight: inherit;
401	  line-height: inherit;
402	  border-radius: 2px;
403	}
404	
405	.btn-link:hover:not(:disabled) {
406	  text-decoration-color: var(--sec-border);
407	}
408	
409	.btn-link:active:not(:disabled) {
410	  text-decoration-color: var(--sec-border);
411	  text-decoration-thickness: 2px;
412	}
413	
414	.btn-link:focus-visible {
415	  outline: 3px solid var(--focus-ring);
416	  outline-offset: 2px;
417	}
418	
419	.btn-link:disabled {
420	  color: var(--link-dis);
421	  text-decoration: none;
422	  cursor: not-allowed;
423	}
424	
425	/* Simulated states */
426	.btn-link.sim-hover  { text-decoration-color: var(--sec-border); }
427	.btn-link.sim-active { text-decoration-color: var(--sec-border); text-decoration-thickness: 2px; }
428	.btn-link.sim-focus  { box-shadow: 0 0 0 3px var(--focus-ring); outline: none; }
429	.btn-link.sim-disabled { color: var(--link-dis); text-decoration: none; pointer-events: none; }
430	
431	
432	/* ─── Icon Inside Text Button ───────────────────────────────── */
433	.btn .bi,
434	.btn svg.btn-icon-svg {
435	  font-size: 1.15em;
436	  line-height: 1;
437	  flex-shrink: 0;
438	}
439	
440	
441	/* ─── Loading / Pending State ───────────────────────────────── */
442	.btn.is-loading {
443	  cursor: wait;
444	  pointer-events: none;
445	  opacity: 0.85;
446	}
447	
448	@keyframes btn-spin {
449	  to { transform: rotate(360deg); }
450	}
451	
452	.btn-spinner {
453	  display: inline-block;
454	  width: 14px;
455	  height: 14px;
456	  border: 2px solid currentColor;
457	  border-top-color: transparent;
458	  border-radius: 50%;
459	  animation: btn-spin 0.65s linear infinite;
460	  flex-shrink: 0;
461	}
462	
463	/* Simulated loading state — documentation only */
464	.btn.sim-loading {
465	  cursor: wait;
466	  pointer-events: none;
467	  opacity: 0.85;
468	}
