471	/* ─── Info Card ─────────────────────────────────────────────── */
472	/*
473	 * A read-only metadata panel for displaying system-supplied context:
474	 * user identity, submission details, IP/date stamps. A warm tinted
475	 * surface creates a subtle visual boundary from editable content.
476	 *
477	 * Usage: place in a fixed 240px sidebar alongside the main content area.
478	 * Always add role="region" and aria-label on .info-card.
479	 * Never place editable fields inside this component.
480	 *
481	 * Dark mode restores the original high-contrast charcoal/lime treatment
482	 * via overrides at the bottom of this file.
483	 */
484	
485	.info-card {
486	  display: flex;
487	  flex-direction: column;
488	  background: #e8e4dc;
489	  border-radius: 6px;
490	  overflow: hidden;
491	  border-top: 4px solid #c4d82e;
492	}
493	
494	.info-card-row {
495	  display: flex;
496	  flex-direction: column;
497	  gap: 4px;
498	  padding: 12px 16px;
499	  border-bottom: 1px solid rgba(0, 0, 0, 0.07);
500	}
501	.info-card-row:last-child { border-bottom: none; }
502	
503	/* Label — muted warm gray, must pass 4.5:1 on card bg #e8e4dc */
504	.info-label {
505	  font-size: 10px;
506	  font-weight: 600;
507	  text-transform: uppercase;
508	  letter-spacing: 0.07em;
509	  color: var(--grey); /* 4.65:1 on #e8e4dc ✓ AA */
510	}
511	
512	/* Value — monospace to signal read-only system data */
513	.info-value {
514	  font-family: "IBM Plex Mono", monospace;
515	  font-size: 12px;
516	  color: #1c1a17;
517	  word-break: break-all;
518	}
519	
520	/* Linked value — monospace, uses system link color */
521	.info-link {
522	  font-family: "IBM Plex Mono", monospace;
523	  font-size: 12px;
524	  color: var(--link);
525	  text-decoration: underline;
526	  text-underline-offset: 2px;
527	}
528	.info-link:hover   { color: var(--link-hover); }
529	.info-link:visited { color: var(--link-visited); }
530	
531	
532	/* ─── Dark Mode Overrides ───────────────────────────────────── */
533	/*
534	 * Fires when: OS is set to dark  AND  the page has not locked to light mode.
535	 *
536	 * To lock a page to light mode, add data-theme="light" to <html>:
537	 *   <html lang="en" data-theme="light">
538	 * The :not([data-theme="light"]) guard prevents this block from applying.
539	 */
540	
541	@media (prefers-color-scheme: dark) {
542	  :root:not([data-theme="light"]) {
543	    /* Secondary button backgrounds — flip to dark lime tint */
544	    --sec-bg:            #1a2306;
545	    --sec-bg-hover:      #212e08;
546	    --sec-bg-active:     #28380a;
547	    --sec-dis-bg:        #1e1e1e;
548	    --sec-dis-border:    #2e2e2e;
549	    --sec-dis-text:      #4e4e4e;
550	
551	    /* Tertiary / icon grey family — lighten for dark bg */
552	    --grey:              #b0aba6; /* 7.62:1 on dark ✓ */
553	    --grey-hover-bg:     #272420;
554	    --grey-hover-dark:   #d4cfc9; /* 11.22:1 on dark ✓ */
555	    --grey-active-bg:    #302c28;
556	    --grey-dis:          #484340;
557	    --grey-ui:           #8b8680; /* 5.91:1 on dark ✓ — same value, passes on both surfaces */
558	    --icon-border:       #8b8680;
559	
560	    /* Primary disabled — dark tint so it doesn't look active */
561	    --lime-dis-bg:       #252f08;
562	    --lime-dis-text:     #5a6b30;
563	
564	    /* Destructive disabled and ghost surfaces */
565	    --danger-dis-bg:     #3a0f0f;
566	    --danger-dis-text:   #864040;
567	    --danger-ghost-hover:  #2a0808;
568	    --danger-ghost-active: #380d0d;
569	
570	    /* Link / content hyperlinks — dark mode */
571	    --link:              #64b5f6; /* Link Blue Dark Mode — 7.84:1 on Repository Brown ✓ AAA */
572	    --link-hover:        #90caf9;
573	    --link-dis:          #484340;
574	    --link-visited:      #c084e0; /* Visited Purple Dark Mode — 6.30:1 on Repository Brown ✓ AA */
575	
576	    /* Focus ring */
577	    --focus-ring:        #64b5f6; /* 7.84:1 on Repository Brown ✓ AAA */
578	
579	    /* Status / alert families — dark surfaces */
580	    --success-bg:        #1e2b0d;
581	    --success-border:    #8fbd3a;
582	    --success-fg:        #c5e1a5; /* 10.4:1 ✓ AAA */
583	    --info-bg:           #132433;
584	    --info-border:       #64b5f6;
585	    --info-fg:           #90caf9; /* 9.0:1 ✓ AAA */
586	    --warning-bg:        #2e2410;
587	    --warning-border:    #e8b800;
588	    --warning-fg:        #ffe082; /* 11.8:1 ✓ AAA */
589	    --error-bg:          #2d1414;
590	    --error-border:      #e57373; /* lighter red, matches dark destructive icon */
591	    --error-fg:          #ef9a9a; /* 8.0:1 ✓ AAA */
592	  }
593	
594	  /* Secondary button — dark lime-tint bg needs lime text, not near-black */
595	  html:not([data-theme="light"]) .btn-secondary         { color: var(--lime); }
596	  html:not([data-theme="light"]) .btn-secondary:disabled,
597	  html:not([data-theme="light"]) .btn-secondary.sim-disabled { color: var(--sec-dis-text); }
598	
599	  /* Destructive icon — #c62828 only 3.09:1 on dark; use lighter red + matching border */
600	  html:not([data-theme="light"]) .btn-icon.btn-icon-destructive                             { color: #e57373; border-color: #e57373; }
601	  html:not([data-theme="light"]) .btn-icon.btn-icon-destructive:hover:not(:disabled),
602	  html:not([data-theme="light"]) .btn-icon.btn-icon-destructive.sim-hover                   { background: var(--danger-ghost-hover);  border-color: #ef9a9a; color: #ef9a9a; }
603	  html:not([data-theme="light"]) .btn-icon.btn-icon-destructive:active:not(:disabled),
604	  html:not([data-theme="light"]) .btn-icon.btn-icon-destructive.sim-active                  { background: var(--danger-ghost-active); border-color: #ef9a9a; color: #ef9a9a; }
605	  html:not([data-theme="light"]) .btn-icon.btn-icon-destructive:disabled,
606	  html:not([data-theme="light"]) .btn-icon.btn-icon-destructive.sim-disabled                { color: var(--danger-dis-text); border-color: var(--icon-border); }
607	
608	  /* Constructive icon — lime border signals variant on dark bg */
609	  html:not([data-theme="light"]) .btn-icon.btn-icon-constructive                            { border-color: var(--lime); }
610	  html:not([data-theme="light"]) .btn-icon.btn-icon-constructive:hover:not(:disabled),
611	  html:not([data-theme="light"]) .btn-icon.btn-icon-constructive.sim-hover                  { background: #2e4a0a; border-color: var(--lime); color: var(--lime); }
612	  html:not([data-theme="light"]) .btn-icon.btn-icon-constructive:active:not(:disabled),
613	  html:not([data-theme="light"]) .btn-icon.btn-icon-constructive.sim-active                 { background: #253a08; border-color: var(--lime); color: var(--lime); }
614	
615	  /* Info card — restore original charcoal + lime treatment in dark mode */
616	  html:not([data-theme="light"]) .info-card                 { background: #2e2b26; }
617	  html:not([data-theme="light"]) .info-card-row             { border-bottom-color: rgba(255,255,255,0.07); }
618	  html:not([data-theme="light"]) .info-label                { color: #cbcdac; }
619	  html:not([data-theme="light"]) .info-value                { color: #c4d82e; }
620	  html:not([data-theme="light"]) .info-link                 { color: #c4d82e; }
621	  html:not([data-theme="light"]) .info-link:hover           { color: #d8ee50; }
622	  html:not([data-theme="light"]) .info-link:visited         { color: #a8c020; }
623	}
