357	<script>
358	  // ── Demo: sortable table ────────────────────────────────────
359	  const table   = document.getElementById('demo-sort-table');
360	  const headers = table.querySelectorAll('th.sortable');
361	  const tbody   = table.querySelector('tbody');
362	
363	  const typeOrder = { new: 0, rep: 1, cross: 2, wdr: 3 };
364	
365	  headers.forEach(th => {
366	    th.addEventListener('click', () => {
367	      const key    = th.dataset.sort;
368	      const wasDesc = th.classList.contains('sort-desc');
369	      const wasAsc  = th.classList.contains('sort-asc');
370	
371	      headers.forEach(h => {
372	        h.classList.remove('sort-asc', 'sort-desc');
373	        h.querySelector('.sort-arrow').textContent = '\u21C5';
374	      });
375	
376	      const dir = wasDesc || !wasAsc ? 'asc' : 'desc';
377	      th.classList.add('sort-' + dir);
378	      th.querySelector('.sort-arrow').textContent = dir === 'asc' ? '\u2191' : '\u2193';
379	
380	      const rows = Array.from(tbody.querySelectorAll('tr'));
381	      rows.sort((a, b) => {
382	        let va, vb;
383	        if (key === 'date') { va = a.dataset.date; vb = b.dataset.date; }
384	        else if (key === 'type') { va = typeOrder[a.dataset.type] ?? 99; vb = typeOrder[b.dataset.type] ?? 99; }
385	        else if (key === 'status') { va = a.dataset.status; vb = b.dataset.status; }
386	        if (va < vb) return dir === 'asc' ? -1 : 1;
387	        if (va > vb) return dir === 'asc' ? 1 : -1;
388	        return 0;
389	      });
390	      rows.forEach(r => tbody.appendChild(r));
391	    });
392	  });
393	</script>
394	</body>
